package com.eventforge.vendor;
import com.eventforge.activity.EventActivityService; import com.eventforge.event.*; import com.eventforge.notification.NotificationService; import com.eventforge.notification.NotificationType; import java.math.BigDecimal; import java.util.UUID; import org.springframework.data.domain.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException;
@Service @Transactional public class VendorService {
 private final VendorRepository vendors; private final VendorPaymentRepository payments; private final EventRepository events; private final EventActivityService activities; private final NotificationService notifications;
 public VendorService(VendorRepository vendors,VendorPaymentRepository payments,EventRepository events,EventActivityService activities,NotificationService notifications){this.vendors=vendors;this.payments=payments;this.events=events;this.activities=activities;this.notifications=notifications;}
 @Transactional(readOnly=true) public Page<VendorDto.Response> list(UUID event,UUID owner,Pageable page){return vendors.findAllOwned(event,owner,page).map(VendorDto.Response::from);}
 public VendorDto.Response create(UUID eventId,UUID owner,VendorDto.Request r){Vendor v=vendors.save(new Vendor(event(eventId,owner),r.name(),r.category(),r.contactName(),r.email(),r.phone(),r.contractedAmount()));record(v.getEvent(),"Vendor created",v.getName(),NotificationType.VENDOR);return VendorDto.Response.from(v);}
 public VendorDto.Response update(UUID event,UUID id,UUID owner,VendorDto.Request r){Vendor v=vendor(event,id,owner);v.update(r.name(),r.category(),r.contactName(),r.email(),r.phone(),r.contractedAmount());record(v.getEvent(),"Vendor updated",v.getName(),NotificationType.VENDOR);return VendorDto.Response.from(v);}
 public void delete(UUID event,UUID id,UUID owner){Vendor v=vendor(event,id,owner);Event e=v.getEvent();String name=v.getName();vendors.delete(v);record(e,"Vendor deleted",name,NotificationType.VENDOR);}
 @Transactional(readOnly=true) public Page<VendorDto.PaymentResponse> listPayments(UUID event,UUID vendor,UUID owner,Pageable page){vendor(event,vendor,owner);return payments.findAllOwned(vendor,owner,page).map(VendorDto.PaymentResponse::from);}
 public VendorDto.PaymentResponse createPayment(UUID event,UUID vendor,UUID owner,VendorDto.PaymentRequest r){Vendor v=vendor(event,vendor,owner);VendorPayment p=payments.save(new VendorPayment(v,r.amount(),r.paidOn(),r.note()));record(v.getEvent(),"Vendor payment created",v.getName(),NotificationType.PAYMENT);return VendorDto.PaymentResponse.from(p);}
 public void deletePayment(UUID event,UUID vendor,UUID payment,UUID owner){Vendor v=vendor(event,vendor,owner); VendorPayment p=payments.findById(payment).filter(x->x.getVendor().getId().equals(vendor)&&x.getVendor().getEvent().getOwner().getId().equals(owner)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Payment not found"));payments.delete(p);record(v.getEvent(),"Vendor payment deleted",v.getName(),NotificationType.PAYMENT);}
 @Transactional(readOnly=true) public VendorDto.PaymentSummary summary(UUID event,UUID vendor,UUID owner){Vendor v=vendor(event,vendor,owner);BigDecimal paid=payments.paidTotal(vendor);BigDecimal contracted=v.getContractedAmount()==null?BigDecimal.ZERO:v.getContractedAmount();return new VendorDto.PaymentSummary(vendor,v.getContractedAmount(),paid,contracted.subtract(paid),payments.countByVendorId(vendor));}
 private void record(Event event,String action,String details,NotificationType type){activities.recordActivity(event,event.getOwner(),action,details);notifications.recordForEventOwner(event,type,action+": "+details);}
 private Event event(UUID id,UUID owner){return events.findById(id).filter(e->e.getOwner().getId().equals(owner)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Event not found"));}
 private Vendor vendor(UUID event,UUID id,UUID owner){return vendors.findById(id).filter(v->v.getEvent().getId().equals(event)&&v.getEvent().getOwner().getId().equals(owner)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Vendor not found"));}
}
